        { "img": bhu1, "title": "Lingaraj Temple", "description": "Bhubaneswar's most iconic landmark and one of the finest examples of Kalinga architecture. This 11th-century temple dedicated to Lord Shiva rises majestically above the city with intricately carved stone structures and a towering spire." },
        { "img": bhu2, "title": "Udayagiri & Khandagiri Caves", "description": "Ancient rock-cut caves dating back to the 2nd century BCE, once inhabited by Jain monks. Features beautifully carved sculptures, inscriptions, meditation chambers, and panoramic viewpoints offering insights into Odisha's ancient history." },
        { "img": bhu3, "title": "Mukteswara Temple", "description": "Known as the Gem of Odisha Architecture, celebrated for exquisite stone carvings, an elegant arched gateway, and intricate sculptures. Regarded as one of India's finest examples of temple craftsmanship." },
        { "img": bhu4, "title": "Nandankanan Zoological Park", "description": "One of India's premier wildlife parks, internationally known for successful breeding of rare white tigers. Home to lions, elephants, reptiles, birds, and endangered species, plus thrilling safari and boating on Kanjia Lake." },
        { "img": bhu5, "title": "Dhauli Shanti Stupa", "description": "One of Odisha's most significant historical sites, marking the location of Emperor Ashoka's famous Kalinga War. The beautiful Peace Pagoda, Buddhist sculptures, and serene surroundings symbolize peace and compassion." },
        { "img": bhu6, "title": "Odisha State Museum", "description": "Showcases an extensive collection of archaeological artifacts, ancient manuscripts, tribal crafts, sculptures, coins, textiles, and traditional artwork — a comprehensive understanding of Odisha's rich cultural legacy." },
        { "img": bhu7, "title": "Rajarani Temple", "description": "Built from distinctive reddish-golden sandstone, admired for elegant architecture and detailed carvings of celestial figures and mythical creatures. One of Bhubaneswar's most beautiful heritage monuments." },
        { "img": bhu8, "title": "Ekamra Haat", "description": "A vibrant cultural marketplace for authentic Odisha handicrafts, handwoven textiles, silver filigree jewelry, Pattachitra paintings, terracotta art, and traditional souvenirs with local cultural performances and regional cuisine." },
        { "img": bhu9, "title": "Bindu Sagar Lake", "description": "One of Bhubaneswar's most sacred water bodies, located beside Lingaraj Temple. Surrounded by ancient temples and peaceful ghats, it offers a serene setting for spiritual reflection and sightseeing." }
