        { "img": ben2, "title": "Cubbon Park", "description": "Often called the city's green lung, covering nearly 300 acres with tree-lined avenues, lush lawns, cycling paths, jogging tracks, ornamental gardens, and historic monuments in the heart of Bengaluru." },
        { "img": ben3, "title": "Bangalore Palace", "description": "Inspired by England's Windsor Castle, this 19th-century palace showcases elegant Tudor-style architecture, grand interiors, royal furniture, intricate wood carvings, vintage paintings, and beautifully landscaped gardens." },
        { "img": ben4, "title": "Vidhana Soudha", "description": "One of Bengaluru's most iconic buildings and a remarkable example of Neo-Dravidian architecture. This granite structure houses the Karnataka State Legislature and is beautifully illuminated during evenings and celebrations." },
        { "img": ben5, "title": "ISKCON Temple Bengaluru", "description": "Among the largest Krishna temples in the world, perched atop a hill combining traditional architecture with modern facilities. Offers peaceful prayer halls, devotional music, spiritual exhibitions, and stunning city views." },
        { "img": ben6, "title": "Bannerghatta Biological Park", "description": "A popular destination for wildlife enthusiasts featuring a zoo, butterfly park, rescue center, and thrilling wildlife safari where visitors can observe tigers, lions, bears, elephants, deer, and numerous bird species." },
        { "img": ben7, "title": "Nandi Hills", "description": "A popular weekend getaway just a short drive from Bengaluru, famous for breathtaking sunrise views, mist-covered landscapes, ancient temples, cycling routes, trekking trails, and pleasant climate year-round." },
        { "img": ben8, "title": "Commercial Street", "description": "One of Bengaluru's busiest shopping destinations, offering branded fashion, traditional clothing, jewelry, footwear, handicrafts, electronics, and souvenirs with a lively atmosphere, cafés, and street food." },
        { "img": ben9, "title": "Tipu Sultan's Summer Palace", "description": "Built entirely from teak wood, this elegant example of Indo-Islamic architecture features beautifully carved pillars, arches, balconies, and historical exhibits showcasing the legacy of Tipu Sultan." },
        { "img": ben10, "title": "Ulsoor Lake", "description": "One of Bengaluru's oldest and largest lakes, providing a peaceful retreat within the bustling city. Enjoy boating, lakeside walks, birdwatching, and scenic sunsets away from the urban rush." }
