        { "title": "Walk Through Montmartre", "description": "Stroll through the charming streets of Montmartre, explore local art galleries, watch street artists at work, and visit the stunning Sacré-Cœur Basilica for panoramic city views." },
        { "title": "Experience French Cafés & Cuisine", "description": "Enjoy authentic French cuisine at traditional cafés and restaurants. Taste delicious croissants, pastries, cheeses, gourmet dishes, and fine French wines while soaking in the city's elegant atmosphere." },
        { "title": "Shop Along Champs-Élysées", "description": "From luxury fashion brands to charming boutiques, the Champs-Élysées offers an exceptional shopping experience. Finish your visit by admiring the magnificent Arc de Triomphe nearby." }
