        { "title": "Explore the Historic Centre", "description": "Walk through UNESCO-listed streets filled with centuries-old churches, temples, colonial buildings, and charming public squares that showcase Macau's unique East-meets-West heritage." },
        { "title": "Ride to the Top of Macau Tower", "description": "Take in breathtaking 360-degree views of the city, the South China Sea, and neighbouring islands. Adventure seekers can also experience thrilling activities like the Skywalk or Bungy Jump." },
        { "title": "Experience Luxury Resorts", "description": "Macau's luxury resorts offer much more than accommodation. Enjoy fine dining, shopping, live entertainment, spas, and beautifully designed interiors that rival the world's best destinations." },
        { "title": "Taste Macau's Unique Cuisine", "description": "Macau's food culture blends Portuguese and Chinese influences to create unforgettable flavours. Don't miss Portuguese egg tarts, African chicken, pork chop buns, seafood dishes, and authentic Macanese cuisine." },
        { "title": "Discover Hidden Streets & Local Markets", "description": "Beyond the famous attractions, Macau rewards curious travellers with colourful alleyways, traditional bakeries, street art, local markets, and cafés where you can experience everyday life like a local." }
