      { "text": "The hotels were outstanding, transfers were seamless, and there was something for everyone — from scenic sightseeing and shopping to entertainment and local food experiences. Macau felt safe, clean, and incredibly welcoming." },
      { "text": "The blend of Portuguese architecture, Chinese traditions, luxury resorts, and warm hospitality made Macau one of the most unique places we've ever travelled. Every recommendation was spot on, and the entire trip exceeded our expectations." }
