        { "title": "Cycle Like a Local", "description": "The Netherlands is one of the world's most bicycle-friendly countries. Rent a bike and explore parks, countryside, villages, and city streets just as the locals do." },
        { "title": "Walk Through Endless Tulip Fields", "description": "During spring, colourful flower fields transform the Dutch countryside into a breathtaking natural masterpiece. It's one of Europe's most iconic seasonal experiences." },
        { "title": "Visit Traditional Windmills & Cheese Farms", "description": "Experience authentic Dutch heritage by touring historic windmills, learning how famous Dutch cheeses are made, and watching artisans create traditional wooden clogs." },
        { "title": "Explore World-Class Museums", "description": "From masterpieces by Rembrandt and Van Gogh to modern art and fascinating history, the Netherlands offers some of Europe's finest museums for every kind of traveller." },
        { "title": "Enjoy Dutch Café Culture", "description": "Relax beside peaceful canals with freshly brewed coffee, warm stroopwafels, Dutch pancakes, or local delicacies while soaking in the welcoming atmosphere that makes the Netherlands so special." }
