        { "img": bahr2, "title": "Bahrain Fort (Qal'at al-Bahrain)", "description": "A UNESCO World Heritage Site and one of the country's most significant historical landmarks. Once the centre of the ancient Dilmun civilisation, offering spectacular views, fascinating ruins, and insight into Bahrain's remarkable past." },
        { "img": bahr3, "title": "Al Fateh Grand Mosque", "description": "One of the largest mosques in the world, admired for stunning Islamic architecture, elegant interiors, and magnificent dome. Guided tours provide an opportunity to learn about Bahrain's culture and traditions." },
        { "img": bahr4, "title": "Manama Souq", "description": "Experience the authentic charm of Bahrain by wandering through the bustling Manama Souq. Browse traditional shops selling spices, perfumes, pearls, textiles, handicrafts, and local delicacies in a vibrant atmosphere." },
        { "img": bahr5, "title": "The Avenues Bahrain", "description": "Located along the waterfront, one of Bahrain's most popular shopping and entertainment destinations featuring international brands, fine dining, cafés, and beautiful sea views." },
        { "img": bahr6, "title": "Bahrain International Circuit", "description": "Home to the Formula 1 Bahrain Grand Prix, this world-class racing circuit offers thrilling motorsport events, driving experiences, and guided tours throughout the year." },
        { "img": bahr7, "title": "Tree of Life", "description": "Standing alone in the middle of the desert for over 400 years, this mysterious tree continues to fascinate visitors from around the world — one of Bahrain's most unique natural attractions." },
        { "img": bahr8, "title": "Muharraq", "description": "The historic city showcasing Bahrain's pearl-diving heritage through beautifully restored traditional houses, museums, narrow alleyways, and cultural landmarks." },
        { "img": bahr9, "title": "Amwaj Islands", "description": "Known for luxury waterfront living, offering beautiful marinas, beach clubs, watersports, fine dining, and a relaxing atmosphere away from the city centre." }
