        { "title": "Discover Traditional Arabian Markets", "description": "Shop for pearls, handcrafted souvenirs, spices, perfumes, jewellery, and local delicacies while exploring Bahrain's lively traditional souqs." },
        { "title": "Enjoy the Beautiful Waterfront", "description": "Take an evening stroll along Bahrain Bay or dine at waterfront restaurants while admiring the illuminated skyline of Manama." },
        { "title": "Taste Authentic Bahraini Cuisine", "description": "Enjoy local favourites such as Machboos, grilled seafood, Bahraini kebabs, sweet halwa, and traditional Arabic coffee while discovering the country's rich culinary heritage." },
        { "title": "Witness a Desert Sunset", "description": "Escape the city and experience the peaceful beauty of Bahrain's desert landscapes. Watching the golden sun set over the Arabian sands is a truly memorable experience." }
