        { "title": "Escape to the Mountain Lakes", "description": "Spend time at Big Almaty Lake, Kolsai Lakes, and Kaindy Lake, where crystal-clear waters and peaceful surroundings create the perfect nature retreat." },
        { "title": "Ride the Cable Car at Shymbulak", "description": "Enjoy panoramic views of the Tian Shan Mountains while riding one of the highest ski resort cable cars in Central Asia." },
        { "title": "Experience Traditional Kazakh Hospitality", "description": "Visit local villages, stay in traditional yurts, taste authentic Kazakh cuisine, and learn about the country's rich nomadic culture." },
        { "title": "Explore Modern Astana", "description": "Discover futuristic architecture, impressive monuments, and vibrant public spaces that reflect Kazakhstan's rapid development and innovation." },
        { "title": "Taste Authentic Kazakh Cuisine", "description": "Try traditional dishes such as Beshbarmak, Kazy, Shashlik, Baursak, and freshly brewed local tea while experiencing the country's warm hospitality." }
